"use strict";
const A=id=>document.getElementById(id),analysisCSRF=document.querySelector('meta[name="csrf-token"]').content;
const stageNames={quality:'影像來源與強度檢核',recognition:'候選辨識／像素量測',explanation:'定位與圖像解釋',segmentation:'分割遮罩',comparison:'獨立參考比對',reconstruction:'三維表面重建',language:'語言／規則摘要',discussion:'術前討論資料檢核'};
const stageStatus={ready:'已完成',blocked:'受阻',not_applicable:'不適用'};
const resultStatus={pending_review:'等待人工覆核',approved:'分析已覆核',rejected:'分析已退回'};
let analysisUser=null,analysisCases=[],analysisStudies=[],selectedCase=null,selectedStudy=null,activeAnalysis=null,analysisBusy=false,caseGeneration=0,meshViewer=null,modelStatus=null,discussionDirty=false,reviewTarget=null;
const flagLabels={acute:'急性警訊',anatomy_reviewed:'解剖與病灶資料已覆核',ischemia_reviewed:'症狀／缺血與功能已覆核',lvef_reviewed:'心室功能資料已覆核',risk_reviewed:'風險與共病資料已覆核',preferences_reviewed:'病人目標與偏好已確認',medication_reviewed:'既有治療與用藥已核對'};
function make(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function notify(message){A('analysisToast').textContent=message;A('analysisToast').hidden=false;setTimeout(()=>A('analysisToast').hidden=true,6000);}
async function analysisAPI(url,options={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':analysisCSRF,...options.headers}}),payload=await response.json();if(response.status===401){location.assign('/');throw Error('請重新登入工作站');}if(!response.ok)throw Error(payload.error||'操作失敗');return payload;}
const send=(url,body)=>analysisAPI(url,{method:'POST',body:JSON.stringify(body)});
const editable=()=>['admin','radiologist'].includes(analysisUser?.role);
const fmt=(x,digits=3)=>typeof x==='number'&&Number.isFinite(x)?x.toLocaleString('zh-TW',{maximumFractionDigits:digits}):'—';
function setLink(id,url,enabled){A(id).href=enabled?url:'#';A(id).setAttribute('aria-disabled',String(!enabled));A(id).tabIndex=enabled?0:-1;}
function markDiscussionDirty(value=true){discussionDirty=value;A('discussionDirtyNotice').hidden=!value;permissions();}
function mayDiscardDiscussion(){return !discussionDirty||window.confirm('術前討論有未保存的檢核或備註。繼續會捨棄這些編輯，確定繼續？');}
function permissions(){
 const may=editable()&&!analysisBusy,pending=activeAnalysis?.status==='pending_review',transferable=activeAnalysis?.integrity?.approvable!==false;
 for(const id of ['executeAnalysis','loadPhantom'])A(id).disabled=!may;
 for(const id of ['analysisCase','recognitionMode','segmentationMode','analysisCenter','analysisThreshold','analysisModel','priorAnalysis','referenceClass'])A(id).disabled=analysisBusy;
 A('analysisThreshold').disabled=analysisBusy||A('segmentationMode').value!=='threshold';A('referenceClassLabel').hidden=!selectedCase?.provided_labels;
 A('analysisUseLLM').disabled=analysisBusy||!(modelStatus?.available_models||[]).length;
 A('approveAnalysis').disabled=!may||!pending||discussionDirty||!transferable;
 A('rejectAnalysis').disabled=!may||!pending||discussionDirty;
 A('saveDiscussion').disabled=!may||!pending;
 A('analysisReviewReason').disabled=!may||!pending;A('clinicianNote').disabled=!may||!pending;
 for(const n of A('discussionChecks').querySelectorAll('select'))n.disabled=!may||!pending;
 for(const n of A('analysisHistory').querySelectorAll('button'))n.disabled=analysisBusy;
 const mesh=activeAnalysis?.reconstruction?.mesh;
 setLink('objExport',`/api/analyses/${activeAnalysis?.id}/mesh.obj`,!!mesh?.vertices.length);
 setLink('stlExport',`/api/analyses/${activeAnalysis?.id}/mesh.stl`,!!mesh?.vertices.length);
 setLink('analysisExport',`/api/analyses/${activeAnalysis?.id}/export`,!!activeAnalysis);
 setLink('reportDraftLink',`/?study=${encodeURIComponent(selectedStudy?.id||'')}&analysis=${activeAnalysis?.id}`,activeAnalysis?.status==='approved'&&!!selectedStudy&&transferable);
}
function switchAnalysisTab(name){document.querySelectorAll('[data-analysis-tab]').forEach(b=>b.classList.toggle('active',b.dataset.analysisTab===name));for(const tab of ['images','comparison','mesh','graph','discussion'])A(tab+'Pane').hidden=tab!==name;if(name==='mesh')requestAnimationFrame(()=>meshViewer?.resize());}
document.querySelectorAll('[data-analysis-tab]').forEach(b=>b.onclick=()=>switchAnalysisTab(b.dataset.analysisTab));
document.querySelectorAll('[data-analysis-close]').forEach(b=>b.onclick=()=>A(b.dataset.analysisClose).close());
A('helpBtn').onclick=()=>A('analysisHelp').showModal();
function factsTable(container,entries){const dl=make('dl',undefined,'stat-grid');for(const [label,value] of entries){dl.append(make('dt',label),make('dd',value===null?'—':String(value)));}container.append(dl);}
async function refreshAnalysisCases(preferred,discardAccepted=false){if(!discardAccepted&&!mayDiscardDiscussion())return;analysisCases=await analysisAPI('/api/cases');analysisStudies=await analysisAPI('/api/hospital/studies');const select=A('analysisCase'),old=preferred||select.value;select.replaceChildren();for(const c of analysisCases){const o=make('option',c.label);o.value=c.id;select.append(o);}select.value=analysisCases.some(c=>c.id===old)?old:(analysisCases.find(c=>c.modality==='MRI')||analysisCases[0])?.id||'';if(select.value)await selectAnalysisCase(true);}
async function selectAnalysisCase(discardAccepted=false){if(analysisBusy)return;if(!discardAccepted&&!mayDiscardDiscussion()){A('analysisCase').value=selectedCase?.id||'';return;}const g=++caseGeneration,priorCaseId=selectedCase?.id;const ident=A('analysisCase').value;analysisBusy=true;permissions();try{const c=await analysisAPI('/api/cases/'+encodeURIComponent(ident));if(g!==caseGeneration)return;activeAnalysis=null;selectedCase=c;A('referenceClass').value='0';A('segmentationMode').querySelector('[value=provided_reference]').disabled=!c.provided_labels;selectedStudy=analysisStudies.find(s=>s.case_id===c.id)||null;A('analysisSource').textContent=`${c.modality} · ${c.slice_count} 張\n${c.synthetic?'合成展示資料':'研究／匯入影像'}\n${c.source}\n${c.source_detail||''}`;A('analysisPatient').textContent=selectedStudy?.patient.name||c.label;A('analysisIdentity').textContent=`MRN ${selectedStudy?.patient_id||'未建檔'} · Accession ${selectedStudy?.accession||'未建檔'} · ${c.modality} · ${c.synthetic?'SYNTHETIC':'RESEARCH'}`;A('analysisCenter').max=c.slice_count;A('analysisCenter').value=c.id.startsWith('demo-ct-')?2:Math.floor(c.slice_count/2)+1;A('analysisSlice').max=c.slice_count-1;A('analysisSlice').value=Number(A('analysisCenter').value)-1;A('recognitionMode').value=c.synthetic?'demo':'inspect';A('segmentationMode').value='threshold';A('analysisThreshold').value=c.reference_mask?120:c.synthetic?240:c.is_hu?130:128;A('thresholdHelp').textContent=c.is_hu?'來源為 CT rescale 強度；閾值區域含所有符合條件的組織，不能當作冠狀動脈分割。':'來源為顯示強度，不能當作 HU。MRI 未驗證間距時只提供 voxel 單位。';A('openStudyLink').href=selectedStudy?`/?study=${encodeURIComponent(selectedStudy.id)}`:'/';clearAnalysisResult();await refreshAnalysisHistory();loadAnalysisImages();permissions();}catch(error){if(g===caseGeneration)A('analysisCase').value=priorCaseId||'';notify(error.message);}finally{if(g===caseGeneration){analysisBusy=false;permissions();}}}
function clearAnalysisResult(){discussionDirty=false;reviewTarget=null;A('discussionDirtyNotice').hidden=true;A('analysisIntegrity').hidden=true;A('analysisReviewReason').value='';A('meshNotice').textContent='尚未建立本次來源的重建結果。';A('analysisBadge').textContent='尚未分析';for(const id of ['metricCandidates','metricVoxels','metricVolume','metricDice'])A(id).textContent='—';for(const id of ['pipelineStages','candidateFacts','detectionComparison','segmentationComparison','priorComparison','qualityStatistics','provenanceGraph','discussionChecks','discussionOptions','clinicalSources','clinicalLimits'])A(id).replaceChildren();A('imageExplanation').textContent='尚未執行本次分析；右側目前顯示原圖，沒有推論疊圖。';A('languageSummary').textContent='';A('languageSource').textContent='';A('graphDetail').textContent='';A('meshDetails').textContent='尚無重建結果。';A('discussionState').textContent='尚未檢核';A('discussionMessage').textContent='';A('clinicianNote').value='';A('executionMessage').textContent='已選擇病例。請核對模式、切片及來源後執行完整分析。';meshViewer?.setMesh({vertices:[],faces:[],units:'voxel'});permissions();}
async function refreshAnalysisHistory(){if(!selectedCase)return;const g=caseGeneration,id=selectedCase.id;const rows=await analysisAPI('/api/analyses?case_id='+encodeURIComponent(id));if(g!==caseGeneration)return;A('analysisHistory').replaceChildren();A('priorAnalysis').replaceChildren();const none=make('option','不比較');none.value='';A('priorAnalysis').append(none);for(const r of rows){const text=`${new Date(r.created_at).toLocaleString('zh-TW',{hour12:false})} · ${r.settings.mode} · v${r.version} · ${resultStatus[r.status]||r.status}`,button=make('button',text,'history-entry');button.onclick=()=>openAnalysis(r.id);A('analysisHistory').append(button);const o=make('option',`${r.id.slice(0,8)} / ${r.settings.mode} / ${r.settings.threshold}`);o.value=r.id;A('priorAnalysis').append(o);}if(!rows.length)A('analysisHistory').append(make('p','尚無本次病例分析。','field-help'));permissions();}
function loadAnalysisImages(){if(!selectedCase)return;const index=Number(A('analysisSlice').value),base=activeAnalysis?`/api/analyses/${activeAnalysis.id}/slices/${index}`:`/api/cases/${selectedCase.id}/slices/${index}`;A('analysisOriginal').src=activeAnalysis?base+'?view=original':base;A('analysisOverlay').src=activeAnalysis?base+'?view='+(A('showOverlay').checked?'overlay':'original'):base;A('analysisSliceLabel').textContent=`${index+1} / ${selectedCase.slice_count}${activeAnalysis&&index!==activeAnalysis.settings.center?' · 非辨識中心切片':''}`;A('overlayCaption').textContent=!activeAnalysis?'尚未分析 · 來源原圖':A('showOverlay').checked?'疊圖：黃框候選／綠色分割 · 各自保留來源':'同一來源原圖 · 疊圖已關閉';}
A('analysisSlice').oninput=loadAnalysisImages;A('showOverlay').onchange=loadAnalysisImages;A('analysisOriginal').onerror=()=>notify('影像無法載入；請檢查登入及來源是否已變更。');A('analysisOverlay').onerror=()=>notify('疊圖無法載入；可能來源或遮罩已變更，請重新分析。');A('segmentationMode').onchange=permissions;A('analysisCase').onchange=()=>selectAnalysisCase();
A('refreshCases').onclick=()=>{if(!analysisBusy)refreshAnalysisCases().catch(e=>notify(e.message));};
A('loadPhantom').onclick=async()=>{if(analysisBusy||!mayDiscardDiscussion())return;analysisBusy=true;permissions();try{const result=await send('/api/analysis/phantom',{});analysisBusy=false;await refreshAnalysisCases(result.case_id,true);A('recognitionMode').value='inspect';A('executionMessage').textContent='已載入獨立解析標籤的 32×96×96 合成殼層；間距為設計值，非病人量測。按執行即可取得遮罩比對與 3D 表面。';}catch(error){notify(error.message);}finally{analysisBusy=false;permissions();}};
A('analysisForm').onsubmit=async event=>{event.preventDefault();if(!selectedCase||analysisBusy||!editable()||!mayDiscardDiscussion())return;const g=caseGeneration;analysisBusy=true;permissions();A('executionMessage').textContent='正在依序執行來源檢核、辨識／量測、解釋、分割、比對、3D 重建及摘要。可選模型可能需要較長時間；請保留此頁。';try{const body={case_id:selectedCase.id,run_id:selectedStudy?.last_run_id||null,mode:A('recognitionMode').value,center:Number(A('analysisCenter').value)-1,threshold:Number(A('analysisThreshold').value),segmentation_mode:A('segmentationMode').value,reference_class:Number(A('referenceClass').value),compare_to:A('priorAnalysis').value||null,use_llm:A('analysisUseLLM').checked,model:A('analysisModel').value};const result=await send('/api/analyses',body);if(g!==caseGeneration)return;activeAnalysis=result;renderAnalysis();await refreshAnalysisHistory();A('executionMessage').textContent='本次流程已保存；請逐項查看完成及受阻項目，再人工覆核。';}catch(error){if(g===caseGeneration)A('executionMessage').textContent=error.message;}finally{analysisBusy=false;permissions();}};
async function openAnalysis(id){if(analysisBusy||!mayDiscardDiscussion())return;const g=caseGeneration;try{const result=await analysisAPI('/api/analyses/'+id);if(g!==caseGeneration||result.case_id!==selectedCase?.id)return;activeAnalysis=result;A('recognitionMode').value=result.settings.mode;A('analysisCenter').value=result.settings.center+1;A('analysisThreshold').value=result.settings.threshold;A('segmentationMode').value=result.settings.segmentation_mode||'threshold';A('referenceClass').value=String(result.settings.reference_class||0);renderAnalysis();A('executionMessage').textContent='已載入保存的分析與版本。';}catch(error){notify(error.message);}}
function renderAnalysis(){const r=activeAnalysis;if(!r)return;discussionDirty=false;reviewTarget=null;A('discussionDirtyNotice').hidden=true;const issues=r.integrity?.approval_blockers||[];A('analysisIntegrity').hidden=!issues.length;A('analysisIntegrity').textContent=issues.join('\n');A('analysisBadge').textContent=`${resultStatus[r.status]||r.status} · v${r.version} · ${r.id.slice(0,8)}`;A('metricCandidates').textContent=r.recognition?(r.recognition.scope==='image_inspection_only'?'未辨識':fmt(r.recognition.candidates.length,0)):'受阻';const stats=r.reconstruction?.statistics;A('metricVoxels').textContent=fmt(stats?.foreground_voxels,0);A('metricVolume').textContent=fmt(stats?.physical_volume_mm3);A('metricDice').textContent=fmt(r.comparison?.segmentation?.dice,4);A('pipelineStages').replaceChildren(...r.stages.map(s=>{const n=make('li');n.dataset.status=s.status;n.append(make('strong',stageNames[s.key]||s.key),make('span',`${stageStatus[s.status]||s.status} / ${s.elapsed_ms} ms`));if(s.reason)n.append(make('p',s.reason));return n;}));A('analysisSlice').value=r.settings.center;loadAnalysisImages();A('imageExplanation').textContent=(r.explanation?.summary||'尚無定位解釋。')+'\n'+(r.explanation?.notice||'');A('candidateFacts').replaceChildren(...(r.explanation?.facts||[]).map(f=>make('div',f.text,'fact-row')));renderComparison();renderMesh();renderGraph();renderDiscussion();A('languageSource').textContent=r.language?`${r.language.source} · ${r.language.model||'無語言模型'} · ${r.language.elapsed_ms} ms${r.language.reason?'\n接續原因：'+r.language.reason:''}`:'未執行語言摘要';A('languageSummary').textContent=r.language?.summary||'';permissions();}
function renderComparison(){const r=activeAnalysis,c=r.comparison||{};for(const id of ['detectionComparison','segmentationComparison','priorComparison','qualityStatistics'])A(id).replaceChildren();const d=c.detection||{};if(d.available){factsTable(A('detectionComparison'),[['TP / FP / FN',`${d.tp} / ${d.fp} / ${d.fn}`],['Precision',fmt(d.precision,4)],['Recall',fmt(d.recall,4)],['F1',fmt(d.f1,4)],['匹配 IoU 門檻',fmt(d.iou_threshold,2)],['平均已配對 IoU',fmt(d.mean_iou,4)]]);A('detectionComparison').append(make('p',d.notice,'metric-note'));}else A('detectionComparison').append(make('p',d.reason||'辨識比對未執行。'));
const s=c.segmentation||{};if(s.available){factsTable(A('segmentationComparison'),[['Dice',fmt(s.dice,5)],['IoU',fmt(s.iou,5)],['預測／參考體素',`${fmt(s.predicted_voxels,0)} / ${fmt(s.reference_voxels,0)}`],['參考 SHA256',s.reference_sha256||'另存於來源紀錄']]);A('segmentationComparison').append(make('p',s.notice,'metric-note'));}else A('segmentationComparison').append(make('p',s.reason||'分割比對未執行。'));const p=c.prior||{};A('priorComparison').append(make('p',p.available?`同一來源候選數差：${p.candidate_count_delta}；參數${p.same_settings?'相同':'不同'}。\n${p.notice}`:p.reason||'尚無可比較分析。'));const q=r.quality?.intensity;if(q)factsTable(A('qualityStatistics'),[['序列尺寸 Z / Y / X',r.source.shape_zyx?.join(' × ')],['最小／最大強度',`${fmt(q.minimum)} / ${fmt(q.maximum)}`],['平均／標準差',`${fmt(q.mean)} / ${fmt(q.std)}`],['強度單位',q.unit],['切片雜湊數',r.source.slice_sha256?.length||0],['空間來源',r.reconstruction?.geometry?.source||'尚未驗證']]);}
function renderMesh(){const result=activeAnalysis?.reconstruction;try{if(!meshViewer)meshViewer=new CardioMeshViewer(A('meshCanvas'),{onStatus:t=>A('meshRenderer').textContent=t});if(result)meshViewer.setMesh(result.mesh);else meshViewer.setMesh({vertices:[],faces:[],units:'voxel'});}catch(error){A('meshRenderer').textContent=error.message;}if(!result){A('meshDetails').textContent='本次沒有可用重建。請查看分割／幾何來源及受阻原因。';A('meshNotice').textContent='沒有本次重建結果；請查看受阻工具，未使用其他來源補上。';return;}const m=result.mesh,g=result.geometry,s=result.statistics;A('meshDetails').textContent=`方法：${result.segmentation.method} / ${m.method}\n${m.vertices.length.toLocaleString()} 頂點 · ${m.faces.length.toLocaleString()} 三角形 · 單位 ${m.units} · ${g.coordinate_system}\n原始形狀 ${s.shape_zyx.join(' × ')}；網格取樣步長 ${m.step_zyx.join(' / ')}\n區域 ${fmt(s.foreground_voxels,0)} 體素；體積 ${s.physical_volume_mm3===null?'未換算（間距未驗證）':fmt(s.physical_volume_mm3)+' mm³'+(activeAnalysis.source.synthetic?'（合成設計）':'（影像標頭）')}\n${g.notice||''}`;A('meshNotice').textContent=result.notice+' STL 不具有可靠的通用單位欄位，請連同分析 JSON 保存。';}
A('resetMesh').onclick=()=>meshViewer?.reset();
function renderGraph(){const holder=A('provenanceGraph');holder.replaceChildren();const graph=activeAnalysis?.graph;if(!graph)return;const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),cols=3,w=870,rowH=110,h=Math.ceil(graph.nodes.length/cols)*rowH+20;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.setAttribute('aria-label','可追溯分析證據關係');const positions=new Map(graph.nodes.map((n,i)=>[n.id,{x:20+(i%cols)*285,y:20+Math.floor(i/cols)*rowH}]));for(const e of graph.edges){const a=positions.get(e.source),b=positions.get(e.target);if(!a||!b)continue;const path=document.createElementNS(ns,'path');path.setAttribute('d',`M${a.x+120},${a.y+50} C${a.x+120},${a.y+90} ${b.x+120},${b.y-35} ${b.x+120},${b.y}`);path.setAttribute('fill','none');path.setAttribute('stroke','#8eabbc');path.setAttribute('stroke-width','1.5');svg.append(path);}for(const n of graph.nodes){const p=positions.get(n.id),group=document.createElementNS(ns,'g'),rect=document.createElementNS(ns,'rect'),label=document.createElementNS(ns,'text'),type=document.createElementNS(ns,'text');group.setAttribute('tabindex','0');group.setAttribute('role','button');group.setAttribute('aria-label',n.label);rect.setAttribute('x',p.x);rect.setAttribute('y',p.y);rect.setAttribute('width','240');rect.setAttribute('height','54');rect.setAttribute('fill',n.kind==='approval'?'#dce8df':'#e5edf3');rect.setAttribute('stroke','#8a9fad');label.setAttribute('x',p.x+12);label.setAttribute('y',p.y+22);label.textContent=n.label;type.setAttribute('x',p.x+12);type.setAttribute('y',p.y+41);type.textContent=n.id;type.setAttribute('font-size','10');group.append(rect,label,type);const select=()=>{A('graphDetail').textContent=JSON.stringify({node:n.id,meaning:n.label,evidence:n.detail,relationships:graph.edges.filter(e=>e.source===n.id||e.target===n.id)},null,2);};group.onclick=select;group.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')select();};svg.append(group);}holder.append(svg);A('graphDetail').textContent='選擇節點，核對本次工具來源、狀態、雜湊與關係。';}
function renderDiscussion(){const d=activeAnalysis?.discussion;if(!d)return;A('discussionState').textContent=({emergency:'急性警訊優先',incomplete:'仍有待補項目',ready_for_mdt:'可交多專業討論，未核准手術'}[d.status]||d.status);A('discussionMessage').textContent=d.message;A('discussionChecks').replaceChildren(...d.checks.map(c=>{const row=make('div',undefined,'discussion-check'),label=make('label',flagLabels[c.key]||c.label),select=make('select');select.id='discussion-'+c.key;label.htmlFor=select.id;for(const [value,text]of [['','未確認'],['true',c.key==='acute'?'有急性警訊':'已由人員核對'],['false',c.key==='acute'?'已確認無急性警訊':'尚未完成']]){const o=make('option',text);o.value=value;select.append(o);}select.value=c.value===null?'':String(c.value);select.onchange=()=>markDiscussionDirty();row.append(label,make('p',c.detail),select);return row;}));A('clinicianNote').value=d.clinical_note?.text||'';A('discussionOptions').replaceChildren(...d.options.map(o=>{const n=make('section',undefined,'discussion-option');n.append(make('h3',o.title),make('p',o.scope),...o.questions.map(t=>make('p',t)));return n;}));A('clinicalSources').replaceChildren(...d.sources.map(s=>{const n=make('section',undefined,'clinical-source'),a=make('a',`${s.year} · ${s.title}`);a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';n.append(a,make('p',s.summary),make('p',`來源類型 ${s.type} · 查核 ${s.accessed_at}`,'field-help'));return n;}));A('clinicalLimits').replaceChildren(...d.evidence_limits.map(t=>make('li',t)));}
A('clinicianNote').oninput=()=>markDiscussionDirty();
A('discussionForm').onsubmit=async event=>{event.preventDefault();if(!activeAnalysis||analysisBusy||!editable())return;const id=activeAnalysis.id,g=caseGeneration,context={clinician_note:A('clinicianNote').value};for(const key of Object.keys(flagLabels)){const v=A('discussion-'+key).value;context[key]=v===''?null:v==='true';}analysisBusy=true;permissions();try{const result=await send(`/api/analyses/${id}/discussion`,{version:activeAnalysis.version,context});if(g===caseGeneration&&activeAnalysis?.id===id){activeAnalysis=result;renderAnalysis();notify('已保存來源與人工檢核，未建立處置或手術醫囑');}}catch(error){notify(error.message);}finally{analysisBusy=false;permissions();}};
A('approveAnalysis').onclick=()=>{
 if(!activeAnalysis||analysisBusy)return;
 if(discussionDirty){notify('請先保存術前討論檢核，再覆核分析');return;}
 if(activeAnalysis.integrity?.approvable===false){notify(activeAnalysis.integrity.approval_blockers.join('；'));return;}
 reviewTarget={id:activeAnalysis.id,version:activeAnalysis.version,generation:caseGeneration};
 const blocked=activeAnalysis.stages.filter(s=>s.status==='blocked').map(s=>stageNames[s.key]||s.key);
 A('analysisReviewSummary').textContent=`${selectedStudy?.patient_id||selectedCase.id} / ${selectedStudy?.accession||'未建檔'} / 分析 ${activeAnalysis.id.slice(0,8)} v${activeAnalysis.version}${blocked.length?'\n受阻項目：'+blocked.join('、'):''}`;
 A('analysisReviewConfirmed').checked=false;A('analysisReviewDialog').showModal();
};
async function reviewAnalysis(decision){
 if(!activeAnalysis||analysisBusy||!editable())return;
 if(discussionDirty){notify('請先保存術前討論檢核，再覆核分析');return;}
 const target=decision==='approve'?reviewTarget:{id:activeAnalysis.id,version:activeAnalysis.version,generation:caseGeneration};
 if(!target||target.id!==activeAnalysis.id||target.version!==activeAnalysis.version||target.generation!==caseGeneration){notify('分析或版本已變更，請重新開啟覆核確認');return;}
 if(decision==='approve'&&!A('analysisReviewConfirmed').checked){notify('請先核對並勾選分析覆核確認');return;}
 if(decision==='reject'&&!A('analysisReviewReason').value.trim()){notify('退回須填寫原因');return;}
 const id=target.id,g=target.generation;analysisBusy=true;permissions();
 try{const result=await send(`/api/analyses/${id}/review`,{version:target.version,decision,reason:A('analysisReviewReason').value,review_confirmed:decision==='approve'&&A('analysisReviewConfirmed').checked});
 if(g===caseGeneration&&activeAnalysis?.id===id){activeAnalysis=result;renderAnalysis();await refreshAnalysisHistory();A('analysisReviewDialog').close();notify(decision==='approve'?'分析覆核已保存，可帶入未簽核報告':'分析已退回，保留來源與原因');}}
 catch(error){notify(error.message);}finally{analysisBusy=false;permissions();}
}
A('confirmAnalysisReview').onclick=()=>reviewAnalysis('approve');A('rejectAnalysis').onclick=()=>reviewAnalysis('reject');
A('analysisStatusBtn').onclick=async()=>{A('analysisModels').showModal();A('analysisModelStatus').textContent='正在檢查本機服務…';try{const [base,extra]=await Promise.all([analysisAPI('/api/demo/status'),analysisAPI('/api/analysis/status')]);A('analysisModelStatus').textContent=JSON.stringify({text_and_speech:base,segmentation_and_3d:extra},null,2);}catch(error){A('analysisModelStatus').textContent=error.message;}};
(async()=>{try{const auth=await analysisAPI('/api/auth/status');analysisUser=auth.user;if(!analysisUser){location.assign('/');return;}A('analysisUser').textContent=`${analysisUser.username} / ${analysisUser.role}`;const id=new URLSearchParams(location.search).get('case');await refreshAnalysisCases(id);A('analysisConnection').textContent='本機 API 已連線';modelStatus=await analysisAPI('/api/demo/status');A('analysisModel').replaceChildren();const none=make('option','不用語言模型');none.value='';A('analysisModel').append(none);for(const m of modelStatus.available_models){const o=make('option',`${m.id} / ${m.recipe}`);o.value=m.id;A('analysisModel').append(o);}A('analysisModel').value=modelStatus.selected_model||'';permissions();const past=new URLSearchParams(location.search).get('analysis');if(past&&/^[0-9a-f]{32}$/.test(past))await openAnalysis(past);}catch(error){A('executionMessage').textContent=error.message;}})();
window.addEventListener('beforeunload',event=>{if(discussionDirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('pagehide',()=>meshViewer?.destroy());
if(typeof ResizeObserver==='function')new ResizeObserver(()=>{if(!A('meshPane').hidden)meshViewer?.resize();}).observe(A('meshCanvas'));
